package android.view;import android.content.Context;import java.util.*;public class ViewGroup extends View{public static class LayoutParams{public static final int WRAP_CONTENT=-2;public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}final List<View> children=new ArrayList<>();public ViewGroup(Context c){super(c);}public void addView(View v){children.add(v);v.parent=this;}public int getChildCount(){return children.size();}public View getChildAt(int i){return children.get(i);}}
